type:
∀ {k d : ℕ} (x : RiffleUpperV2.Prefix k d) (i j : Fin ↑x.fst) (D : Finset (Fin k)),
  ↑j < ↑i →
    RiffleUpperV2.Anchor.prefixThenDigits x i D (RiffleUpperV2.Anchor.prefixColumn x j) = {List.Vector.get x.snd j}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} (s : RiffleUpperV2.Anchor.SuffixSide) (R : Finset (Fin n))
  (x : RiffleUpperV2.Prefix k d) (j : Fin ↑x.fst) (ω : RiffleUpperV2.Sample cuts),
  have P := RiffleUpperV2.Anchor.unequalEndpointParams s R x j ω;
  have A := RiffleUpperV2.Anchor.unequalExposedRows s R x j ω;
  have D := s.allowed (List.Vector.get x.snd j);
  P.population = n - A.card ∧
    P.marked = (RiffleUpperV2.Anchor.residualAllowed A D (ω (RiffleUpperV2.Anchor.prefixColumn x j))).card ∧
      P.draws = (RiffleUpperV2.Anchor.unequalSampleRows s R x j ω).card ∧
        P.population - P.marked =
          (RiffleUpperV2.Anchor.residualAllowed A (Finset.univ \ D) (ω (RiffleUpperV2.Anchor.prefixColumn x j))).card

∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleUpperV2.Anchor.swappedParams p =
    { population := p.population, marked := p.draws, draws := p.marked, marked_le := ⋯, draws_le := ⋯ }

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {j : Fin d} (A : Finset (Fin n)) (D : Finset (Fin k))
  (c : TimeProfile.ColumnAssignments cuts j),
  RiffleUpperV2.Anchor.residualAllowed A D c = {r ∈ Finset.univ \ A | ↑c r ∈ D}

∀ {k n d : ℕ} {cuts : RiffleUpperV2.Cuts k n d} {j : Fin d} (a : Fin k) (c₀ : TimeProfile.ColumnAssignments cuts j),
  RiffleUpperV2.Anchor.residualMarked (RiffleUpperV2.Anchor.equalityRows a c₀) {x : Fin k | x < a} c₀ =
    RiffleUpperV2.Hypergeometric.allowedCount cuts j {x : Fin k | x < a}
